// Objective: pull contact_id + the raw note text from the webhook customData.
// The 'note' field is the full WAVV note string (same text we used to read from contact notes).
const b = ($json && $json.body) ? $json.body : $json;
const cd = b.customData || {};
return { json: {
  contact_id: String(b.contact_id || cd.contact_id || '').trim(),
  note_raw:   String(cd.note || b.note || '').trim()
}};

const n = $('Normalize').item.json;
const raw = String(n.note_raw || '');

// known dispositions (slugs) — same list the Dispatcher / Cold Handler use
const KNOWN = ['cold-good','cold-bad','cold-on-hold','gatekeeper-good','gatekeeper-bad','gatekeeper-on-hold','conversation-active','conversation-active-on-hold','appointment-booked','sales-call','not-interested-right-now-good','not-interested-right-now-bad','do-not-contact','voicemail','call-center','bad-number','not-a-fit'];

// Flag: only WAVV-format notes carry a disposition. Notes look like:
//   [ WAVV: <uuid> ] To: ... From: ... Duration: ... Disposition: <text> Tag: <tag> Note: <note>
// Other note types are ignored.
const is_wavv = /\[\s*WAVV:\s*[^\]]+\]/i.test(raw);   // marker present, any id format

let disposition = '', note = '', is_missed = false;
if (is_wavv) {
  // Disposition: <text> Tag:   (Tag always follows a present Disposition)
  const dm = raw.match(/Disposition:\s*([\s\S]*?)\s*Tag:/i);
  const dispText = dm ? dm[1].trim() : '';

  // Missed-call awareness: a 'No Answer' / 'Canceled' WAVV disposition means the call never
  // connected -> treat as a missed call and DON'T touch the Call Disposition / Call Notes fields
  // (the missed-call automation owns that lead). Matches 'no answer', 'canceled', 'cancelled'.
  is_missed = /(no[\s-]*answer|cancell?ed)/i.test(dispText);

  const dispSlug = dispText.toLowerCase().replace(/\s+/g, '-');
  disposition = (KNOWN.indexOf(dispSlug) >= 0) ? dispSlug : '';   // keep only if recognised

  // Note: <text>  (to end of line)
  const nm = raw.match(/Note:\s*([\s\S]*)$/i);
  const noteVal = nm ? nm[1].trim() : '';
  note = (!noteVal || noteVal.toLowerCase() === 'auto-disposition') ? '' : noteVal;
}

// Write the fields only for a real WAVV disposition that isn't a missed call.
const should_update = is_wavv && !is_missed;

return { json: { contact_id: n.contact_id, is_wavv: is_wavv, is_missed: is_missed, should_update: should_update, disposition: disposition, note: note } };

const gc = $json || {};
const contact = gc.contact || gc || {};
const tags = Array.isArray(contact.tags) ? contact.tags : [];
// keep only the auto-added WAVV tags (any tag starting with 'wavv-', case-insensitive)
const wavv_tags = tags.filter(t => String(t).toLowerCase().startsWith('wavv-'));
return { json: {
  contact_id: String($('Parse Disposition + Note').item.json.contact_id || '').trim(),
  wavv_tags: wavv_tags,
  has_wavv_tags: wavv_tags.length > 0
}};
